INSERT INTO card VALUES(176,'A.replace(''old'', ''new'')','Replaces all instances of a specified substring, ''old'', within a string with another substring, ''new''. the function takes two arguments, both of which are strings: ''old'', the substring to be replaced, and ''new'', the substring to replace ''old'' with. the variable containing the original string is passed as an object.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1.4399999999999999467,'2023-03-18 13:33:13.626640',2,2,2,'extract','2023-03-18 13:15:23.965302','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
