INSERT INTO card VALUES(188,'Round()','The round() function takes a number and an optional number of digits as arguments and returns the rounded number. in the passage, it is used to round the result of len(test_yourself) / 2 to the nearest whole number.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.984301',0,0,0,'extract','2023-03-18 13:15:23.984301','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(189,'Test_yourself[]','This is not technically a function, but rather a way to access elements in a list. in the passage, it is used to access an element in the list at a specific index. the index is calculated using the formula: round(len(test_yourself) / 2) - 1, which is then used in the brackets to access the element at that index.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.985545',0,0,0,'extract','2023-03-18 13:15:23.985545','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(190,'Sorted()','Sorted() is a python function that takes an iterable (a list, tuple, set, etc.) as an argument and returns a new sorted list with the elements in ascending order. it can also take the arguments key (a function to specify the sorting criterion), reverse (a boolean to specify if the list should be sorted in reverse order) and stable (a boolean to specify if the sorting should maintain order of equal elements).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.986552',0,0,0,'extract','2023-03-18 13:15:23.986552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(191,'.upper()','.upper() is a python method that only works with strings. it returns a new string where all letters are converted to uppercase. it takes no arguments.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.988583',0,0,0,'extract','2023-03-18 13:15:23.988583','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(192,'Append()','Append() is a python method that adds an element to the end of a list. it takes one argument, which is the element to be added.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.989581',0,0,0,'extract','2023-03-18 13:15:23.989581','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(193,'Type()','Type() is a python function that returns the type of an object. it takes one argument, which is the object to be checked.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.991552',0,0,0,'extract','2023-03-18 13:15:23.991552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(194,'Range()','Range() is a python function that returns a range object which represents a sequence of numbers. it takes one to three arguments: start (the first number in the sequence, defaults to 0), stop (the last number in the sequence, exclusive), and step (the increment between numbers, defaults to 1).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.992552',0,0,0,'extract','2023-03-18 13:15:23.993552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(195,'Min()','Min() is a python function that returns the smallest item in an iterable (a list, tuple, set, etc.). it can also take multiple iterable arguments and return the smallest item across all of them. it takes one or more arguments, each of which is the iterable to be checked.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.997552',0,0,0,'extract','2023-03-18 13:15:23.997552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(196,'Max()','Max() is a python function that returns the largest item in an iterable (a list, tuple, set, etc.). it can also take multiple iterable arguments and return the largest item across all of them. it takes one or more arguments, each of which is the iterable to be checked.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:23.998552',0,0,0,'extract','2023-03-18 13:15:23.998552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(197,'Abs()','Abs() is a python function that returns the absolute value of a number (the distance from 0). it takes one argument, which is the number to be checked.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.001551',0,0,0,'extract','2023-03-18 13:15:24.001551','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(198,'Float()','Float() is a python function that converts a number or a string representing a number to a floating-point number (a number with a decimal point). it takes one argument, which is the object to be converted.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.002551',0,0,0,'extract','2023-03-18 13:15:24.002551','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(199,'Int()','Int() is a python function that converts a number or a string representing a number to an integer (a whole number). it takes one or two arguments: x (the number or string to be converted) and base (the base of the number if x is a string). if no base is provided, the default is base 10.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.003551',0,0,0,'extract','2023-03-18 13:15:24.003551','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(200,'Zip()','Zip() is a python function that aggregates elements from multiple iterables (lists, tuples, etc.) into tuples. it returns an iterator of tuples, where the i-th tuple contains the i-th element from each of the input iterables. it takes one or more iterables as arguments.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.005552',0,0,0,'extract','2023-03-18 13:15:24.005552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(201,'Enumerate()','Enumerate() is a python function that adds a counter to an iterable (a list, tuple, set, etc.) and returns it as an enumerate object. the enumerate object returns pairs of the form (index, item), where index is a counter starting from 0, and item is the corresponding element from the iterable. it takes one iterable as an argument.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.007552',0,0,0,'extract','2023-03-18 13:15:24.007552','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(202,'Filter()','Filter() is a python function that returns an iterator consisting of the elements from an iterable (a list, tuple, set, etc.) for which a given function returns true. the function is applied to each element of the iterable to determine if it should be included in the resulting iterator. it takes two arguments: function (the function to apply to each element) and iterable (the iterable to filter).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.009558',0,0,0,'extract','2023-03-18 13:15:24.009558','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(203,'Map()','Map() is a python function that applies a given function to each element of an iterable (a list, tuple, set, etc.) and returns an iterator of the resulting values. the function is applied to each element of the iterable to generate the corresponding value in the resulting iterator. it takes two or more arguments: function (the function to apply to each element) and one or more iterables (the iterables to apply the function to). the iterables must have the same length, and the function must take as many arguments as there are iterables.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-18 13:15:24.010551',0,0,0,'extract','2023-03-18 13:15:24.010551','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(204,'Pep 8 ÔÇô style guide for python code','This is the title of the style guide.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.094220',0,0,0,'extract','2023-03-19 10:31:48.094220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(205,'Guido van rossum <guido at python.org>, barry warsaw <barry at python.org>, nick coghlan <ncoghlan at gmail.com>','These are the authors of the style guide.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.096219',0,0,0,'extract','2023-03-19 10:31:48.096219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(206,'Active','This indicates the current status of the style guide.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.098218',0,0,0,'extract','2023-03-19 10:31:48.098218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(207,'Process','This describes the type of the style guide.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.099218',0,0,0,'extract','2023-03-19 10:31:48.099218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(208,'05-jul-2001','This is the date when the style guide was first created.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.101218',0,0,0,'extract','2023-03-19 10:31:48.101218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(209,'05-jul-2001, 01-aug-2013','These are the dates when the style guide was last updated.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.102218',0,0,0,'extract','2023-03-19 10:31:48.102218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(210,'Introduction','This is the section of the style guide that provides an overview of the document.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.104219',0,0,0,'extract','2023-03-19 10:31:48.104219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(211,'A foolish consistency is the hobgoblin of little minds','This is a quote that emphasizes the importance of readability and consistency in code.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.105219',0,0,0,'extract','2023-03-19 10:31:48.105219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(212,'Consistency with this style guide is important. consistency within a project is more important. consistency within one module or function is the most important. however, know when to be inconsistent ÔÇô sometimes style guide recommendations just arenÔÇÖt applicable. when in doubt, use your best judgment. look at other examples and decide what looks best. and donÔÇÖt hesitate to ask! in particular: do not break backwards compatibility just to comply with this pep! some other good reasons to ignore a particular guideline: when applying the guideline would make the code less readable, even for someone who is used to reading code that follows this pep. to be consistent with surrounding code that also','These are the guidelines and recommendations for coding in python according to the style guide.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.107220',0,0,0,'extract','2023-03-19 10:31:48.107220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(213,'Code lay-out','Use 4 spaces per indentation level.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.109220',0,0,0,'extract','2023-03-19 10:31:48.109220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(214,'Indentation','All lines of code should be indented to 4 spaces. this pep takes no explicit position on how (or whether) to further visually distinguish conditional lines from the nested suite inside the if-statement. acceptable options in this situation include, but are not limited to: no extra indentation, add a comment, which will provide some distinction in editors supporting syntax highlighting, and add some extra indentation on the conditional continuation line.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.117221',0,0,0,'extract','2023-03-19 10:31:48.117221','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(215,'Line breaks','The closing brace/bracket/parenthesis on multiline constructs may either line up under the first non-whitespace character of the last line of the list, or it may be lined up under the first character of the line that starts the multiline construct.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.120219',0,0,0,'extract','2023-03-19 10:31:48.120219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(216,'Tabs and spaces','Spaces are the preferred indentation method. tabs should be used solely to remain consistent with code that is already indented with tabs. python disallows mixing tabs and spaces for indentation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.121219',0,0,0,'extract','2023-03-19 10:31:48.121219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(217,'Maximum line length','All lines should be limited to a maximum of 79 characters. for flowing long blocks of text with fewer structural restrictions, such as docstrings or comments, the line length should be limited to 72 characters. this is to avoid disrupting the visual structure of the code and makes it more manageable when using code review tools that present the two versions in adjacent columns.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.125219',0,0,0,'extract','2023-03-19 10:31:48.125219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(218,'Line length limit','The python standard library requires limiting lines to 79 characters (and docstrings/comments to 72).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.127219',0,0,0,'extract','2023-03-19 10:31:48.127219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(219,'Wrapping long lines','The preferred way of wrapping long lines is by using pythonÔÇÖs implied line continuation inside parentheses, brackets and braces.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.128219',0,0,0,'extract','2023-03-19 10:31:48.128219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(220,'Breaking over multiple lines','Long lines can be broken over multiple lines by wrapping expressions in parentheses. these should be used in preference to using a backslash for line continuation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.130219',0,0,0,'extract','2023-03-19 10:31:48.130219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(221,'Indentation of continued lines','Make sure to indent the continued line appropriately.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.131219',0,0,0,'extract','2023-03-19 10:31:48.131219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(222,'Line break with binary operators','It is recommended to break before binary operators as breaking after binary operators can hurt readability.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.132219',0,0,0,'extract','2023-03-19 10:31:48.132219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(223,'Use blank lines to separate logical sections','Suggests using blank lines sparingly to indicate logical sections within functions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.134220',0,0,0,'extract','2023-03-19 10:31:48.134220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(224,'Use the control-l (i.e. ^l) form feed character as whitespace to separate same purpose unrelated functions','Python accepts the control-l form feed character as whitespace, which can be used to separate unrelated functions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.135219',0,0,0,'extract','2023-03-19 10:31:48.135219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(225,'Surround top-level function and class definitions with two blank lines','Specifies using two blank lines to surround top-level function and class definitions, and using a single blank line between method definitions inside a class.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.137219',0,0,0,'extract','2023-03-19 10:31:48.137219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(226,'Source file encoding','Specifies that code in the core python distribution should always use utf-8 encoding and not have an encoding declaration. non-utf-8 encodings should be used only for test purposes, non-ascii characters should be used sparingly and ascii-only identifiers, preferably using english words, must be used in the python standard library.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.139219',0,0,0,'extract','2023-03-19 10:31:48.139219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(227,'Use knuthÔÇÖs style for breaking formulas in python code','Encourages following knuthÔÇÖs style for breaking formulas, which suggests breaking displayed formulas before binary operations and formulas within a paragraph after binary operations and relations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.142219',0,0,0,'extract','2023-03-19 10:31:48.142219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(228,'Imports should usually be on separate lines','Imports should usually be on separate lines, with one import statement per line, correct usage is shown.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.144220',0,0,0,'extract','2023-03-19 10:31:48.144220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(229,'Imports are always put at the top of the file and grouped in a specific order','Imports should be put at the top of the file, just after any module comments and docstrings, and before module globals and constants. imports should be grouped in the following order: standard library imports, related third party imports, local application/library specific imports. a blank line should be put between each group of imports.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.145220',0,0,0,'extract','2023-03-19 10:31:48.145220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(230,'Absolute imports are recommended','Absolute imports are recommended, and are usually more readable and tend to be be better behaved in case the import system is configured incorrectly. however, explicit relative imports are acceptable, especially when dealing with complex package layouts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.147219',0,0,0,'extract','2023-03-19 10:31:48.147219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(231,'When importing a class, it is usually okay to spell the import','When importing a class from a class-containing module, it''s usually okay to spell this: from myclass import myclass from foo.bar.yourclass import yourclass. if this spelling causes local name clashes, then the imports should be spelled explicitly.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.148218',0,0,0,'extract','2023-03-19 10:31:48.148218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(232,'Wildcard imports should be avoided except for one use case','Wildcard imports (from <module> import *) should be avoided as it''s difficult to know which names are present in the namespace, except for a specific use case, which is to republish an internal interface as part of a public api.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.150219',0,0,0,'extract','2023-03-19 10:31:48.150219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(233,'Module level dunder names','Names with two leading and two trailing underscores should be placed after the module docstring but before any import statements except from __future__ imports.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.151219',0,0,0,'extract','2023-03-19 10:31:48.151219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(234,'String quotes','When a string contains single or double quote characters, use the other one to avoid backslashes in the string. for triple-quoted strings, always use double quote characters to be consistent with the docstring convention in pep 257.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.153220',0,0,0,'extract','2023-03-19 10:31:48.153220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(235,'Whitespace in expressions and statements pet peeves','Avoid extraneous whitespace in certain situations, such as immediately inside parentheses, brackets, or braces and before a comma, semicolon, or colon. however, in a slice, the colon acts like a binary operator and should have equal amounts of spacing on either side, treating it as the operator with the lowest priority. in an extended slice, both colons must have the same amount of spacing applied. an exception to this rule is when a slice parameter is omitted.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.154220',0,0,0,'extract','2023-03-19 10:31:48.154220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(236,'Style guide rules','Always surround indexing or slicing with a single space before and after, do not use more than one space.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.158220',0,0,0,'extract','2023-03-19 10:31:48.158220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(237,'Other recommendations','Avoid trailing whitespace anywhere as it can be confusing and some editors do not preserve it. pre-commit hooks on many projects reject it.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.163219',0,0,0,'extract','2023-03-19 10:31:48.163219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(238,'Use spaces around -> arrow','When using the -> arrow, there should be spaces around it if present.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.170219',0,0,0,'extract','2023-03-19 10:31:48.170219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(239,'DonÔÇÖt use spaces around = sign','Do not use spaces around the = sign when used to indicate a keyword argument or a default value for an unannotated function parameter.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.171219',0,0,0,'extract','2023-03-19 10:31:48.171219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(240,'Use spaces when combining an argument annotation with a default value','When combining an argument annotation with a default value, use spaces around the = sign.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.175220',0,0,0,'extract','2023-03-19 10:31:48.175220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(241,'Avoid using compound statements','Avoid using compound statements which include multiple statements on the same line.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.177220',0,0,0,'extract','2023-03-19 10:31:48.177220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(242,'Never put multi-clause statements on the same line','Never put multi-clause statements, such as if/for/while, on the same line.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.178218',0,0,0,'extract','2023-03-19 10:31:48.178218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(243,'Use trailing commas when necessary','Trailing commas are optional, but are necessary for tuples of one element. they are also helpful for lists of values, arguments, or imported items when using version control.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.180217',0,0,0,'extract','2023-03-19 10:31:48.180217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(244,'Put each value on a line by itself','The pattern is to put each value (etc.) on a line by itself, always adding a trailing comma, and add the close parenthesis/bracket/brace on the next line. however it does not make sense to have a trailing comma on the same line as the closing delimiter (except in the above case of singleton tuples).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.182218',0,0,0,'extract','2023-03-19 10:31:48.182218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(245,'Always keep comments up-to-date','Comments that contradict the code are worse than no comments. always make a priority of keeping the comments up-to-date when the code changes!.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.183218',0,0,0,'extract','2023-03-19 10:31:48.183218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(246,'Use complete sentences and capitalize the first word of comments','Comments should be complete sentences. the first word should be capitalized, unless it is an identifier that begins with a lower case letter (never alter the case of identifiers!).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.185217',0,0,0,'extract','2023-03-19 10:31:48.185217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(247,'Use one or two spaces after a sentence-ending period in multi-sentence comments','Block comments generally consist of one or more paragraphs built out of complete sentences, with each sentence ending in a period. you should use one or two spaces after a sentence-ending period in multi-sentence comments, except after the final sentence.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.186217',0,0,0,'extract','2023-03-19 10:31:48.186217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(248,'Write comments in english','Ensure that your comments are clear and easily understandable to other speakers of the language you are writing in. python coders from non-english speaking countries: please write your comments in english, unless you are 120% sure that the code will never be read by people who donÔÇÖt speak your language.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.187217',0,0,0,'extract','2023-03-19 10:31:48.187217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(249,'Indent block comments and separate paragraphs by a line containing a single #','Block comments generally apply to some (or all) code that follows them, and are indented to the same level as that code. each line of a block comment starts with a # and a single space (unless it is indented text inside the comment). paragraphs inside a block comment are separated by a line containing a single #.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.189218',0,0,0,'extract','2023-03-19 10:31:48.189218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(250,'Use inline comments sparingly and separate them by at least two spaces from the statement','Use inline comments sparingly. an inline comment is a comment on the same line as a statement. inline comments should be separated by at least two spaces from the statement. they should start with a #.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.192219',0,0,0,'extract','2023-03-19 10:31:48.192219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(251,'Inline comments','Inline comments are unnecessary and distracting if they state the obvious.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.195218',0,0,0,'extract','2023-03-19 10:31:48.195218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(252,'Docstrings','Write docstrings for all public modules, functions, classes, and methods. docstrings are not necessary for non-public methods, but you should have a comment that describes what the method does. pep 257 describes good docstring conventions. multiline docstrings should end with the closing """ on a line by itself. one-liner docstrings should keep the closing """ on the same line.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.196218',0,0,0,'extract','2023-03-19 10:31:48.196218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(253,'Naming conventions','New modules and packages should follow the current recommended naming standards, but internal consistency is preferred over complete consistency with the standards. public names should reflect usage rather than implementation. there are different naming styles, including single lowercase and uppercase letters, lowercase words with underscores, uppercase words with underscores, and capitalizedwords (also known as camelcase or studlycaps). when using acronyms in capitalizedwords, capitalize all the letters of the acronym.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.198217',0,0,0,'extract','2023-03-19 10:31:48.198217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(254,'Mixed case style','Use mixed case for multiword names, with the first letter of each word in capitalized form.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.199219',0,0,0,'extract','2023-03-19 10:31:48.199219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(255,'Avoid using all caps with underscores','Avoid using all capital letters.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.200217',0,0,0,'extract','2023-03-19 10:31:48.200217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(256,'Unique prefix style','Use a short unique prefix to group related names together. this can be done to emphasize the correspondence with the fields of the posix system call struct or to group related names in a library such as x11.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.202217',0,0,0,'extract','2023-03-19 10:31:48.202217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(257,'Naming convention for special forms','Leading or trailing underscores are recognized as special forms in python, each with their own specific use case.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.203217',0,0,0,'extract','2023-03-19 10:31:48.203217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(258,'Names to avoid','Avoid using the characters ÔÇÿlÔÇÖ, ÔÇÿoÔÇÖ, or ÔÇÿiÔÇÖ as single character variable names because they are indistinguishable from the numerals 1 and 0.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.204217',0,0,0,'extract','2023-03-19 10:31:48.204217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(259,'Ascii compatibility for standard library identifiers','Identifiers used in the python standard library must be ascii compatible.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.206217',0,0,0,'extract','2023-03-19 10:31:48.206217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(260,'Package and module naming conventions','Modules should have short, all-lowercase names. underscores can be used in the module name if it improves readability. python packages should also have short, all-lowercase names.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.208224',0,0,0,'extract','2023-03-19 10:31:48.208224','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(261,'Short, all-lowercase names','Names are recommended to be all lowercase, with underscores discouraged.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.210217',0,0,0,'extract','2023-03-19 10:31:48.210217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(262,'Class names','Class names should use the capwords convention.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.211217',0,0,0,'extract','2023-03-19 10:31:48.211217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(263,'Type variable names','Type variable names should use capwords, with short names like t, anystr, num preferred. they should have a suffix of _co or _contra to indicate covariant or contravariant behavior.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.212217',0,0,0,'extract','2023-03-19 10:31:48.212217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(264,'Exception names','Exception names should use the class naming convention and have a suffix of ''error'' if appropriate.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.214217',0,0,0,'extract','2023-03-19 10:31:48.214217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(265,'Global variable names','Global variable names should follow the same convention as function names, and should either be prefixed with an underscore or use the __all__ mechanism to prevent exporting.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.215217',0,0,0,'extract','2023-03-19 10:31:48.215217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(266,'Function and variable names','Function and variable names should be all lowercase, using underscores to improve readability. mixedcase is allowed only in contexts where thatÔÇÖs already the prevailing style.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.216217',0,0,0,'extract','2023-03-19 10:31:48.216217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(267,'Function and method arguments','Arguments for functions and methods should always use ''self''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.218217',0,0,0,'extract','2023-03-19 10:31:48.218217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(268,'Use cls for the first argument to class methods','For the first argument to instance methods, always use cls for the first argument to class methods.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.219217',0,0,0,'extract','2023-03-19 10:31:48.219217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(269,'Use a single trailing underscore for function argument name clashes','If a function argumentÔÇÖs name clashes with a reserved keyword, it is generally better to append a single trailing underscore rather than use an abbreviation or spelling corruption.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.220217',0,0,0,'extract','2023-03-19 10:31:48.220217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(270,'Use function naming rules for method names and instance variables','Use the function naming rules: lowercase with words separated by underscores as necessary to improve readability. use one leading underscore only for non-public methods and instance variables. to avoid name clashes with subclasses, use two leading underscores to invoke pythonÔÇÖs name mangling rules.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.222217',0,0,0,'extract','2023-03-19 10:31:48.222217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(271,'Constants should be defined in all capital letters','Constants are usually defined on a module level and written in all capital letters with underscores separating words.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.223218',0,0,0,'extract','2023-03-19 10:31:48.223218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(272,'Choose non-public for attributes if in doubt','Always decide whether a classÔÇÖs methods and instance variables (collectively: ÔÇ£attributesÔÇØ) should be public or non-public. if in doubt, choose non-public.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.225220',0,0,0,'extract','2023-03-19 10:31:48.225220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(273,'Public attributes should have no leading underscores','Public attributes should not start with an underscore to distinguish them from private attributes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.227218',0,0,0,'extract','2023-03-19 10:31:48.227218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(274,'If public attribute name collides with reserved keyword, append a single trailing underscore','If a public attribute name conflicts with a reserved keyword, add a trailing underscore to the attribute name instead of using an abbreviation or misspelling.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.228218',0,0,0,'extract','2023-03-19 10:31:48.228218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(275,'Preferably use `cls` for any variable or argument which is a class','`cls` is the preferred spelling for any variable or argument which is known to be a class, especially the first argument to a class method.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.229218',0,0,0,'extract','2023-03-19 10:31:48.229218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(276,'For simple public data attributes, expose just attribute name without complicated accessor/mutator methods','For simple public data attributes, it is best to expose just the attribute name without complicated accessor/mutator methods; use properties to hide functional implementation behind simple data attribute access syntax when adding functional behavior.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.231218',0,0,0,'extract','2023-03-19 10:31:48.231218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(277,'Avoid using properties for computationally expensive operations','Avoid using properties for computationally expensive operations since the attribute notation makes the caller believe that access is relatively cheap; keep functional behavior side-effect free if possible, but side-effects such as caching are generally fine.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.232219',0,0,0,'extract','2023-03-19 10:31:48.232219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(278,'Name attributes with double leading underscores and no trailing underscores to not allow subclasses to use them','If there are attributes you donÔÇÖt want subclasses to use, consider naming them with double leading underscores and no trailing underscores to invoke pythonÔÇÖs name mangling algorithm, where the name of the class is mangled into the attribute name; this helps avoid attribute name collisions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.233217',0,0,0,'extract','2023-03-19 10:31:48.233217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(279,'Name mangling','Name mangling can cause name collisions and make certain uses less convenient.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.234218',0,0,0,'extract','2023-03-19 10:31:48.234218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(280,'Public and internal interfaces','Clear distinction should be made between public and internal interfaces. documented interfaces are considered public, while undocumented interfaces and those explicitly declared provisional or internal are considered internal. modules should declare names in their public api using the __all__ attribute.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.236218',0,0,0,'extract','2023-03-19 10:31:48.236218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(281,'Programming recommendations','Code should be written to avoid disadvantaging other implementations of python, and should not rely on cpython''s specific optimizations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.237218',0,0,0,'extract','2023-03-19 10:31:48.237218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(282,'Use ''''.join() instead of + for concatenation in performance sensitive areas','This ensures concatenation happens in linear time across implementations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.239218',0,0,0,'extract','2023-03-19 10:31:48.239218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(283,'Use is or is not for none comparisons','Do not use the equality operators as they may give unexpected results. also beware of using ''if x'' as a shorthand for ''if x is not none'' especially with variables that can have types that evaluate to false in a boolean context.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.241220',0,0,0,'extract','2023-03-19 10:31:48.241220','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(284,'Use is not instead of not...is for none comparisons','Both expressions are functionally identical but is not is more readable and preferred.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.242219',0,0,0,'extract','2023-03-19 10:31:48.242219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(285,'Implement all six operations when implementing ordering operations with rich comparisons','This avoids confusion and errors when comparisons are used in different contexts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.243219',0,0,0,'extract','2023-03-19 10:31:48.243219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(286,'Use a def statement instead of an assignment statement that binds a lambda expression directly to an identifier','This makes the code more readable and avoids potential confusion.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.245218',0,0,0,'extract','2023-03-19 10:31:48.245218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(287,'Name function objects properly','Use the specific name ''f'' instead of the generic ''<lambda>''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.246218',0,0,0,'extract','2023-03-19 10:31:48.246218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(288,'Derive exceptions from exception','Do not derive exceptions directly from baseexception unless catching them is almost always wrong.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.248218',0,0,0,'extract','2023-03-19 10:31:48.248218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(289,'Design exception hierarchies based on intended usage','Create exception hierarchies designed to answer the question ''what went wrong?'' rather than simply stating ''a problem occurred.''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.249218',0,0,0,'extract','2023-03-19 10:31:48.249218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(290,'Follow class naming conventions for exceptions','Suffix exception class names with ''error'' if applicable for error exceptions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.250219',0,0,0,'extract','2023-03-19 10:31:48.250219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(291,'Use exception chaining appropriately','Use explicit replacement without losing the original traceback by using ''raise x from y''. preserve relevant details, such as attribute names or original exception message.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.251219',0,0,0,'extract','2023-03-19 10:31:48.251219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(292,'Be specific when catching exceptions','Mention specific exceptions when possible instead of using a bare except: clause. a bare except: clause may catch systemexit and keyboardinterrupt exceptions and can hide other problems. use ''except exception:'' to catch all exceptions signaling program errors.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.253217',0,0,0,'extract','2023-03-19 10:31:48.253217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(293,'Limit use of bare except clauses','Bare except clauses should only be used when printing out or logging the traceback or if code needs to do some cleanup work but then lets the exception propagate upwards with raise. try...finally can be a better way to handle this case. when catching operating system errors, prefer the explicit exception hierarchy introduced in python 3.3 over introspection of errno values. additionally, for all try/except clauses, limit the try clause to the absolute minimum amount of code necessary.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.254218',0,0,0,'extract','2023-03-19 10:31:48.254218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(294,'Use with statement or try/finally for cleaning up resources','Use a with statement or try/finally statement to clean up a resource promptly and reliably after use. context managers should be invoked through separate functions or methods whenever they do something other than acquire and release resources.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.255217',0,0,0,'extract','2023-03-19 10:31:48.255217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(295,'Be consistent in return statements','All return statements in a function should return an expression, or none of them should. if any return statement returns an expression, any return statements where no value is returned should explicitly state this as return none, and an explicit return statement should be present at the end of the function (if reachable).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.257219',0,0,0,'extract','2023-03-19 10:31:48.257219','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(296,'Use ''''.startswith() and ''''.endswith() instead of string slicing to check for prefixes or suffixes.','Startswith() and endswith() are cleaner and less error prone.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.259218',0,0,0,'extract','2023-03-19 10:31:48.259218','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(297,'Object type comparisons should always use isinstance() instead of comparing types directly:','Use isinstance() for comparing types directly.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.260217',0,0,0,'extract','2023-03-19 10:31:48.260217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(298,'For sequences, (strings, lists, tuples), use the fact that empty sequences are false:','Use ''if not seq:'' or ''if seq:'' instead of ''if len(seq):'' or ''if not len(seq):''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.262217',0,0,0,'extract','2023-03-19 10:31:48.262217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(299,'DonÔÇÖt write string literals that rely on significant trailing whitespace.','Avoid using string literals which include significant trailing whitespace.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.263217',0,0,0,'extract','2023-03-19 10:31:48.263217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(300,'DonÔÇÖt compare boolean values to true or false using ==:','Use ''if x:'' or ''if not x:'' instead of ''if x == true:'' or ''if x == false:''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.264217',0,0,0,'extract','2023-03-19 10:31:48.264217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(301,'Use of the flow control statements return/break/continue within the finally suite of a try...finally, where the flow control statement would jump outside the finally suite, is discouraged.','Avoid using return/break/continue within the finally suite of a try...finally.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.266217',0,0,0,'extract','2023-03-19 10:31:48.266217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(302,'Function annotations','Function annotations should use pep 484 syntax.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.267217',0,0,0,'extract','2023-03-19 10:31:48.267217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(303,'Annotations usage','Function annotations can be used for new code and big refactorings. comment ''# type: ignore'' can be added to ignore all annotations for a specific code. type checkers are optional in python and are not issued by default. users are free to ignore them. stub files (.pyi) are recommended for third party library packages.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.268217',0,0,0,'extract','2023-03-19 10:31:48.268217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(304,'Variable annotations style guide','Annotations for module level variables, class and instance variables, and local variables should have a single space after the colon. there should be no space before the colon. if an assignment has a right-hand side, then the equality sign should have exactly one space on both sides.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,1,'2023-03-19 10:31:48.269217',0,0,0,'extract','2023-03-19 10:31:48.269217','Custom',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(305,'Brexit','The withdrawal of the united kingdom from the european union.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8743.6800000000002913,'2023-03-23 11:04:27.216938',8,6,5,'extract','2023-03-22 11:30:30.586703','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(306,'Northern ireland','A region of the united kingdom located in the northern part of the island of ireland.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:24.671992',7,6,5,'extract','2023-03-22 11:30:30.589704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(307,'Agreement','A negotiated and typically legally binding arrangement between parties.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:25.810674',6,5,5,'extract','2023-03-22 11:30:30.591704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(308,'European union','A political and economic union of 27 member states located primarily in europe.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.0,88012.79999999998836,'2023-03-23 11:04:26.279609',6,6,6,'extract','2023-03-22 11:30:30.592704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(309,'Prime minister','The head of government in parliamentary systems such as those of the united kingdom.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.0,88012.79999999998836,'2023-03-23 11:04:27.465462',6,6,6,'extract','2023-03-22 11:30:30.594706','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(310,'Deputy pm','The second highest position in governments in parliamentary systems.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:21.099005',6,5,5,'extract','2023-03-22 11:30:30.595703','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(311,'Trade','The action of buying and selling goods and services.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:22.024527',8,5,5,'extract','2023-03-22 11:30:30.596703','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(312,'No 10 ','A term used to describe the prime minister''s office at 10 downing street.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.0,8726.3999999999996362,'2023-03-23 11:04:20.772469',7,5,0,'extract','2023-03-22 11:30:30.598704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(313,'Taoiseach','The prime minister of ireland.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:23.024983',7,5,5,'extract','2023-03-22 11:30:30.599704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(314,'Leadership','The action of leading a group of people or an organization.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.0,88012.79999999998836,'2023-03-23 11:04:23.941422',6,6,6,'extract','2023-03-22 11:30:30.600704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO card VALUES(315,'Northern ireland protocol','An agreement designed to avoid a hard border between northern ireland and the republic of ireland after brexit.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,8726.3999999999996362,'2023-03-23 11:04:28.732724',6,5,5,'extract','2023-03-22 11:30:30.601704','Definitions',0,1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
