INSERT INTO deck_files VALUES(1,'test_file upload_Definitions_2023-03-16 11:40:26.077243',NULL,NULL,NULL,'In physics,┬á gravity┬á(from┬áLatin┬ágravitas┬á''weight'' [1]) is a┬áfundamental interaction ┬áwhich causes mutual  attraction between all things with┬á mass┬áor┬áenergy. Gravity is, by far, the weakest of the four fundamental interactions, approximately 10 38┬átimes weaker than the┬á strong interaction , 1036┬átimes weaker than  the┬áelectromagnetic force ┬áand 10 29┬átimes weaker than the┬á weak interaction . As a result, it has no  significant influence at the level of┬á subatomic particles .[2]┬áHowever, gravity is the most significant  interaction between objects at the┬á macroscopic scale , and it determines the motion  of┬áplanets,┬ástars,┬ágalaxies, and even┬á light. On Earth , gravity gives┬á weight┬áto┬áphysical objects , and the┬á Moon''s gravity ┬áis responsible for  sublunar┬á tides┬áin the oceans (the corresponding antipodal tide is caused by the inertia of the Earth and  Moon orbiting one another). Gravity also has many important biological functions, helping to guide the  growth of plants through the process of┬á gravitropism ┬áand influencing the┬á circulation ┬áof fluids  in┬ámulticellular organisms . Investigation into the effects of┬á weightlessness ┬áhas shown that gravity may  play a role in┬á immune system ┬áfunction and┬á cell differentiation ┬áwithin the human body. The gravitational attraction between the original gaseous matter in the┬á Universe ┬áallowed it  to┬ácoalesce ┬áand┬áform stars ┬áwhich eventually condensed into galaxies, so gravity is responsible for many of the large-scale structures in the Universe. Gravity has an infinite range, although its effects become  weaker as objects get farther away.','source','2023-03-16 11:40:26.077243');
INSERT INTO deck_files VALUES(2,'test_file upload_Definitions_2023-03-16 11:46:21.502999',NULL,NULL,NULL,'In physics,┬á gravity┬á(from┬áLatin┬ágravitas┬á''weight'' [1]) is a┬áfundamental interaction ┬áwhich causes mutual  attraction between all things with┬á mass┬áor┬áenergy. Gravity is, by far, the weakest of the four fundamental interactions, approximately 10 38┬átimes weaker than the┬á strong interaction , 1036┬átimes weaker than  the┬áelectromagnetic force ┬áand 10 29┬átimes weaker than the┬á weak interaction . As a result, it has no  significant influence at the level of┬á subatomic particles .[2]┬áHowever, gravity is the most significant  interaction between objects at the┬á macroscopic scale , and it determines the motion  of┬áplanets,┬ástars,┬ágalaxies, and even┬á light. On Earth , gravity gives┬á weight┬áto┬áphysical objects , and the┬á Moon''s gravity ┬áis responsible for  sublunar┬á tides┬áin the oceans (the corresponding antipodal tide is caused by the inertia of the Earth and  Moon orbiting one another). Gravity also has many important biological functions, helping to guide the  growth of plants through the process of┬á gravitropism ┬áand influencing the┬á circulation ┬áof fluids  in┬ámulticellular organisms . Investigation into the effects of┬á weightlessness ┬áhas shown that gravity may  play a role in┬á immune system ┬áfunction and┬á cell differentiation ┬áwithin the human body. The gravitational attraction between the original gaseous matter in the┬á Universe ┬áallowed it  to┬ácoalesce ┬áand┬áform stars ┬áwhich eventually condensed into galaxies, so gravity is responsible for many of the large-scale structures in the Universe. Gravity has an infinite range, although its effects become  weaker as objects get farther away.','source','2023-03-16 11:46:21.502999');
