INSERT INTO job VALUES(1,2,'22023-03-24T16:12:49.039090','Definitions','completed',0,'{"deck": 13, "text": "In physics,\u00a0 gravity\u00a0(from\u00a0Latin\u00a0gravitas\u00a0''weight'' [1]) is a\u00a0fundamental interaction \u00a0which causes mutual  attraction between all things with\u00a0 mass\u00a0or\u00a0energy. Gravity is, by far, the weakest of the four fundamental interactions, approximately 10 38\u00a0times weaker than the\u00a0 strong interaction , 1036\u00a0times weaker than  the\u00a0electromagnetic force \u00a0and 10 29\u00a0times weaker than the\u00a0 weak interaction . As a result, it has no  significant influence at the level of\u00a0 subatomic particles .[2]\u00a0However, gravity is the most significant  interaction between objects at the\u00a0 macroscopic scale , and it determines the motion  of\u00a0planets,\u00a0stars,\u00a0galaxies, and even\u00a0 light. On Earth , gravity gives\u00a0 weight\u00a0to\u00a0physical objects , and the\u00a0 Moon''s gravity \u00a0is responsible for  sublunar\u00a0 tides\u00a0in the oceans (the corresponding antipodal tide is caused by the inertia of the Earth and  Moon orbiting one another). Gravity also has many important biological functions, helping to guide the  growth of plants through the process of\u00a0 gravitropism \u00a0and influencing the\u00a0 circulation \u00a0of fluids  in\u00a0multicellular organisms . Investigation into the effects of\u00a0 weightlessness \u00a0has shown that gravity may  play a role in\u00a0 immune system \u00a0function and\u00a0 cell differentiation \u00a0within the human body. The gravitational attraction between the original gaseous matter in the\u00a0 Universe \u00a0allowed it  to\u00a0coalesce \u00a0and\u00a0form stars \u00a0which eventually condensed into galaxies, so gravity is responsible for many of the large-scale structures in the Universe. Gravity has an infinite range, although its effects become  weaker as objects get farther away.", "prompt_options": {"main_opt": "Definitions", "subject_opt": null, "trans_opt": "English", "lang_opt": null, "detail_lvl_opt": null, "min_opt": null, "max_opt": null, "images_opt": null, "save_text_opt": null, "custom_term": null, "custom_content": null}}',0,NULL,NULL,'2023-03-24 16:12:49.040090',NULL,NULL,NULL,NULL);
INSERT INTO job VALUES(2,2,'22023-03-24T18:52:56.724588','Definitions','completed',0,'{"deck": 14, "text": "ello world, this is my first post here. I have been learning django for quite some time and working on an idea for a lot of time. I wanted to deploy my website using pythonanywhere. I have tried deploying using theirs'' free service and sort of got the confidence to figure out error and debug those while deploying. So, I wanted to use their premium service to deploy it properly without any lagging and the ''.pythonanywhere.com'' sub-domain. So can you suggest me the premium packages I should go for starting a starup of sort (more like a dream of launching a website) .    As for the project, it is basically a competition hosting website to host image content type competition. It has the User model and user profiles and user uploaded contents (media files). In the front end, it uses basic html and css and a little bit of Javascript and Jquery.    Lastly I have been using the db.sqlite3 (the django default database) for my project. I was thinking of continuing using that. I am not super good at using Postgres or MySQL and at the near future there shouldn''t be any traffic to my website (if I ever launch it). So should I continue using that and if the answer is yes when should I consider migrating to something else. If no then should I take the database services of pythonanywhere as well and can you provide any workable tutorials for doing just that ?", "prompt_options": {"main_opt": "Definitions", "subject_opt": null, "trans_opt": "English", "lang_opt": null, "detail_lvl_opt": null, "min_opt": null, "max_opt": null, "images_opt": null, "save_text_opt": null, "custom_term": null, "custom_content": null}}',0,NULL,NULL,'2023-03-24 18:52:56.725589',NULL,NULL,NULL,NULL);
INSERT INTO job VALUES(3,2,'22023-03-24T19:31:14.670961','Definitions','completed',0,'{"deck": 15, "text": "One of the reasons everybody loves Python is the interactive shell. It basically allows you to execute Python commands in real time and immediately get results back. Flask itself does not come with an interactive shell, because it does not require any specific setup upfront, just import your application and start playing around.  There are however some handy helpers to make playing around in the shell a more pleasant experience. The main issue with interactive console sessions is that you\u2019re not triggering a request like a browser does which means that g, request and others are not available. But the code you want to test might depend on them, so what can you do?  This is where some helper functions come in handy. Keep in mind however that these functions are not only there for interactive shell usage, but also for unit testing and other situations that require a faked request context.  Generally it\u2019s recommended that you read The Request Context first.  Command Line Interface Starting with Flask 0.11 the recommended way to work with the shell is the flask shell command which does a lot of this automatically for you. For instance the shell is automatically initialized with a loaded application context.  For more information see Command Line Interface.  Creating a Request Context The easiest way to create a proper request context from the shell is by using the test_request_context method which creates us a RequestContext:  ctx = app.test_request_context() Normally you would use the with statement to make this request object active, but in the shell it\u2019s easier to use the push() and pop() methods by hand:  ctx.push() From that point onwards you can work with the request object until you call pop:  ctx.pop() Firing Before/After Request By just creating a request context, you still don\u2019t have run the code that is normally run before a request. This might result in your database being unavailable if you are connecting to the database in a before-request callback or the current user not being stored on the g object etc.  This however can easily be done yourself. Just call preprocess_request():  ctx = app.test_request_context() ctx.push() app.preprocess_request() Keep in mind that the preprocess_request() function might return a response object, in that case just ignore it.  To shutdown a request, you need to trick a bit before the after request functions (triggered by process_response()) operate on a response object:  app.process_response(app.response_class()) <Response 0 bytes [200 OK]> ctx.pop() The functions registered as teardown_request() are automatically called when the context is popped. So this is the perfect place to automatically tear down resources that were needed by the request context (such as database connections).  Further Improving the Shell Experience If you like the idea of experimenting in a shell, create yourself a module with stuff you want to star import into your interactive session. There you could also define some more helper methods for common things such as initializing the database, dropping tables etc.  Just put them into a module (like shelltools) and import from there:  from shelltools import *", "prompt_options": {"main_opt": "Definitions", "subject_opt": null, "trans_opt": "English", "lang_opt": null, "detail_lvl_opt": null, "min_opt": null, "max_opt": null, "images_opt": null, "save_text_opt": null, "custom_term": null, "custom_content": null}}',0,NULL,NULL,'2023-03-24 19:31:14.671938',NULL,NULL,NULL,NULL);
INSERT INTO job VALUES(4,2,'22023-03-25T09:06:24.028488','Definitions','completed',1,'{"deck": 11, "text": "In physics, gravity(fromLatingravitas''weight'' [1]) is afundamental interaction which causes mutual  attraction between all things with massorenergy. Gravity is, by far, the weakest of the four fundamental interactions, approximately 10 38times weaker than the strong interaction , 1036times weaker than  theelectromagnetic force and 10 29times weaker than the weak interaction . As a result, it has no  significant influence at the level of subatomic particles .[2]However, gravity is the most significant  interaction between objects at the macroscopic scale , and it determines the motion  ofplanets,stars,galaxies, and even light. On Earth , gravity gives weighttophysical objects , and the Moon''s gravity is responsible for  sublunar tidesin the oceans (the corresponding antipodal tide is caused by the inertia of the Earth and  Moon orbiting one another). Gravity also has many important biological functions, helping to guide the  growth of plants through the process of gravitropism and influencing the circulation of fluids  inmulticellular organisms . Investigation into the effects of weightlessness has shown that gravity may  play a role in immune system function and cell differentiation within the human body. The gravitational attraction between the original gaseous matter in the Universe allowed it  tocoalesce andform stars which eventually condensed into galaxies, so gravity is responsible for many of the large-scale structures in the Universe. Gravity has an infinite range, although its effects become  weaker as objects get farther away.", "prompt_options": {"main_opt": "Definitions", "subject_opt": null, "trans_opt": "English", "lang_opt": null, "detail_lvl_opt": null, "min_opt": null, "max_opt": null, "images_opt": null, "save_text_opt": null, "custom_term": null, "custom_content": null}}',0,NULL,NULL,'2023-03-25 09:06:24.029488',NULL,NULL,NULL,NULL);
