SET foreign_key_checks = 0;
START TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE usage_records (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	operation_type VARCHAR(50) NOT NULL, 
	operation_details VARCHAR(1000), 
	operation_count INTEGER NOT NULL, 
	remaining_count INTEGER NOT NULL, 
	time_period VARCHAR(50) NOT NULL, 
	limit_count INTEGER NOT NULL, 
	date DATETIME NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	source_ip VARCHAR(50), 
	payment_status VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE card (
	id INTEGER NOT NULL, 
	term VARCHAR(1000) NOT NULL, 
	content VARCHAR(1000) NOT NULL, 
	boc_2 VARCHAR(255), 
	boc_3 VARCHAR(255), 
	boc_4 VARCHAR(255), 
	formula VARCHAR(255), 
	img VARCHAR(255), 
	sound VARCHAR(255), 
	boc_id FLOAT, 
	box_id FLOAT, 
	srs_interval INT, 
	time_updated DATETIME, 
	times_asked INTEGER, 
	times_correct INTEGER, 
	times_correct_row INTEGER, 
	create_method VARCHAR(255), 
	time_created DATETIME, 
	category VARCHAR(255), 
	edited INTEGER, 
	diff_lvl FLOAT, 
	subject VARCHAR(255), 
	topic VARCHAR(255), 
	prompt_option VARCHAR(255), 
	prompt_option2 VARCHAR(255), 
	trans_option VARCHAR(255), 
	len_option VARCHAR(255), 
	qmin_option VARCHAR(255), 
	qmax_option VARCHAR(255), 
	PRIMARY KEY (id)
);
CREATE TABLE deck_files (
	id INTEGER NOT NULL, 
	file_name VARCHAR(100), 
	file_path VARCHAR(50), 
	file_type VARCHAR(500), 
	file_size VARCHAR(50), 
	text_string TEXT, 
	create_type VARCHAR(50), 
	time_created DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE feedback (
	id INTEGER NOT NULL, 
	name VARCHAR(50), 
	email VARCHAR(120), 
	message VARCHAR(500), 
	timestamp DATETIME, 
	type_feedback VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE question (
	id INTEGER NOT NULL, 
	question VARCHAR(1000) NOT NULL, 
	term VARCHAR(1000) NOT NULL, 
	content VARCHAR(1000) NOT NULL, 
	boc_2 VARCHAR(1000), 
	boc_3 VARCHAR(1000), 
	boc_4 VARCHAR(1000), 
	formula VARCHAR(255), 
	prompt_option VARCHAR(255), 
	q_type VARCHAR(50), 
	q_order INTEGER, 
	points INTEGER, 
	PRIMARY KEY (id)
);
CREATE TABLE response_data (
	id INTEGER NOT NULL, 
	prompt TEXT, 
	response TEXT, 
	content TEXT, 
	timestamp DATETIME, 
	success BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE deck (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	user_id INTEGER, 
	time_created DATETIME, 
	time_updated DATETIME, 
	creator INTEGER, 
	public INTEGER, 
	edited INTEGER, 
	create_method VARCHAR(255), 
	category VARCHAR(255), 
	times_accessed INTEGER, 
	access_date DATETIME, 
	subject VARCHAR(255), 
	topic VARCHAR(255), 
	shared BOOLEAN, 
	accepted BOOLEAN, 
	sharer INTEGER, 
	share_date DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE shared_decks (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	sender INTEGER, 
	receiver INTEGER, 
	time_created DATETIME, 
	creator INTEGER, 
	public INTEGER, 
	edited INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(receiver) REFERENCES user (id), 
	FOREIGN KEY(sender) REFERENCES user (id)
);
CREATE TABLE test (
	id INTEGER NOT NULL, 
	name VARCHAR(50), 
	points INTEGER, 
	num_questions INTEGER, 
	category VARCHAR(50), 
	subject VARCHAR(50), 
	topic VARCHAR(50), 
	time_created DATETIME, 
	due_date DATETIME, 
	creator INTEGER, 
	result_reveal BOOLEAN, 
	answer_reveal BOOLEAN, 
	time_limit INTEGER, 
	instructions VARCHAR(255), 
	description VARCHAR(255), 
	shuffle BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(creator) REFERENCES user (id)
);

CREATE TABLE cards (
	card_id INTEGER, 
	deck_id INTEGER, 
	FOREIGN KEY(card_id) REFERENCES card (id), 
	FOREIGN KEY(deck_id) REFERENCES deck (id)
);
CREATE TABLE cards_shared (
	card_id INTEGER, 
	shared_decks_id INTEGER, 
	FOREIGN KEY(card_id) REFERENCES card (id), 
	FOREIGN KEY(shared_decks_id) REFERENCES shared_decks (id)
);
CREATE TABLE distribution (
	test_id INTEGER, 
	taker_id INTEGER, 
	FOREIGN KEY(taker_id) REFERENCES user (id), 
	FOREIGN KEY(test_id) REFERENCES test (id)
);
CREATE TABLE question_result (
	id INTEGER NOT NULL, 
	test_id INTEGER, 
	taker INTEGER, 
	question_id INTEGER, 
	answer VARCHAR(50), 
	points INTEGER, 
	timestamp DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(question_id) REFERENCES question (id), 
	FOREIGN KEY(taker) REFERENCES user (id), 
	FOREIGN KEY(test_id) REFERENCES test (id)
);
CREATE TABLE questions (
	test_id INTEGER, 
	question_id INTEGER, 
	FOREIGN KEY(question_id) REFERENCES question (id), 
	FOREIGN KEY(test_id) REFERENCES test (id)
);
CREATE TABLE source_files (
	deck_file_id INTEGER, 
	deck_id INTEGER, 
	FOREIGN KEY(deck_file_id) REFERENCES deck_files (id), 
	FOREIGN KEY(deck_id) REFERENCES deck (id)
);
CREATE TABLE test_result (
	id INTEGER NOT NULL, 
	test_id INTEGER, 
	taker INTEGER, 
	creator INTEGER, 
	due_date DATETIME, 
	start_time DATETIME, 
	end_time DATETIME, 
	points INTEGER, 
	correct INTEGER, 
	blank INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(creator) REFERENCES user (id), 
	FOREIGN KEY(taker) REFERENCES user (id), 
	FOREIGN KEY(test_id) REFERENCES test (id)
);
CREATE TABLE IF NOT EXISTS `subscription_plans` (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	description VARCHAR(200), 
	limit_count INTEGER NOT NULL, 
	limit_time_period VARCHAR(50) NOT NULL, 
	price FLOAT NOT NULL, duration INTEGER, 
	PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS `user`(
	id INTEGER NOT NULL, 
	subscription_start_date DATETIME, 
	latest_roll_over DATETIME, 
	subscription_plan INTEGER NOT NULL, 
	username VARCHAR(20), 
	password VARCHAR(80), 
	email VARCHAR(255) NOT NULL, 
	email_confirmed_at DATETIME, 
	first_name VARCHAR(50), 
	last_name VARCHAR(50), 
	external_id VARCHAR(255), 
	external_type VARCHAR(255), 
	time_created DATETIME, 
	time_accessed DATETIME, 
	account_type VARCHAR(255), 
	account_status VARCHAR(255), 
	account_expiration DATETIME, 
	account_expiration_reason VARCHAR(255), 
	gender VARCHAR(255), 
	pic VARCHAR(255), 
	contacted_email BOOLEAN, 
	dob DATETIME, 
	timezone VARCHAR(64), 
	PRIMARY KEY (id), 
	CONSTRAINT fk_sub_plan FOREIGN KEY(subscription_plan) REFERENCES subscription_plans (id), 
	UNIQUE (username)
);
CREATE TABLE IF NOT EXISTS `subscriber` (
	id INTEGER NOT NULL, 
	email VARCHAR(120), 
	timestamp DATETIME, first_name VARCHAR(50), last_name VARCHAR(50), 
	PRIMARY KEY (id), 
	UNIQUE (email)
);
CREATE TABLE job (
	id INTEGER NOT NULL, 
	user INTEGER, 
	slug VARCHAR(64) NOT NULL, 
	task_type VARCHAR(64), 
	state VARCHAR(10) NOT NULL, 
	result INTEGER, 
	payload TEXT, 
	priority INTEGER NOT NULL, 
	start_time DATETIME, 
	end_time DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	error_message TEXT, 
	error_traceback TEXT, 
	error_type VARCHAR(64), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user) REFERENCES user (id)
);
CREATE INDEX ix_feedback_timestamp ON feedback (timestamp);
CREATE INDEX ix_response_data_timestamp ON response_data (timestamp);
CREATE INDEX ix_subscriber_timestamp ON subscriber (timestamp);
COMMIT;
